'use client'

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { cn } from '@/lib/utils'
import type { BadgeTone } from '@/registry/satin/ui/badge'
import { useSatinLabels } from '@/registry/satin/ui/labels'

/**
 * Chip, 1:1 with the uiKit `Chip` set (3206:79959): Subtle or Outline, md (28, control-height)
 * or sm (24, control-height-xs), eight tones like Badge, an optional dot, avatar and remove
 * button. Label medium 13/19.5, 8px side padding; the dot, avatar and close slots overlap
 * the label padding by 4px, as in Figma.
 *
 * Neutral is its own look: Outline is a popover surface with a border-default edge and an
 * xs drop shadow, Subtle is the secondary action fill. Every other tone uses the `tone/*`
 * tokens (repointed by `data-tone`): tone-bg fill, tone-border edge, tone-fg text; hover and
 * pressed fill with tone-border.
 *
 * States (satin-hover / satin-focus / satin-pressed, or `data-force`):
 * - hover: neutral outline bg-hover + border-strong; neutral subtle bg/pressed fill.
 * - pressed: neutral bg/pressed fill with a border-strong edge, no drop shadow.
 * - focus: the 2px action/focus-ring spread, border-strong edge, no drop shadow.
 * - disabled: 50% opacity, no drop shadow.
 * Subtle pressed's 1px edge is an inset shadow so the chip doesn't grow by 2px.
 *
 * With `onRemove` the chip is a `span` holding a real remove button (a button can't hold
 * a button); without it, the chip itself is the button.
 */
const chipVariants = cva(
  [
    'sa:group/chip sa:relative sa:inline-flex sa:shrink-0 sa:items-center sa:rounded-pill sa:whitespace-nowrap sa:select-none',
    'sa:text-sm sa:leading-(--sa-text-sm--line-height) sa:font-medium',
    'sa:transition-[background-color,border-color,color,box-shadow] sa:duration-(--sa-duration-fast) sa:ease-(--sa-ease-out)',
    'sa:focus-visible:outline-none',
    'sa:data-[disabled]:pointer-events-none sa:data-[disabled]:opacity-50 sa:data-[disabled]:[box-shadow:none]',
  ],
  {
    variants: {
      variant: {
        outline: 'sa:border sa:border-strong',
        subtle: '',
      },
      size: {
        md: 'sa:h-control-height',
        sm: 'sa:h-control-height-xs',
      },
      neutral: { true: 'sa:text-text-default', false: 'sa:text-tone-fg' },
    },
    compoundVariants: [
      {
        variant: 'sa:outline',
        neutral: true,
        className: [
          'sa:border-border-default sa:bg-bg-popover sa:[box-shadow:0_1px_2px_0_var(--sa-effect-shadow-xs)]',
          'sa:satin-hover:border-border-strong sa:satin-hover:bg-bg-hover',
          'sa:satin-focus:border-border-strong sa:satin-focus:bg-bg-popover sa:satin-focus:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
          'sa:has-[button:focus-visible]:border-border-strong sa:has-[button:focus-visible]:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
          'sa:satin-pressed:border-border-strong sa:satin-pressed:bg-bg-pressed sa:satin-pressed:[box-shadow:none]',
          'sa:data-[disabled]:border-border-strong',
        ],
      },
      {
        variant: 'sa:outline',
        neutral: false,
        className: [
          'sa:border-tone-border sa:bg-tone-bg sa:[box-shadow:0_1px_2px_0_var(--sa-effect-shadow-xs)]',
          'sa:satin-hover:bg-tone-border',
          'sa:satin-focus:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
          'sa:has-[button:focus-visible]:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
          'sa:satin-pressed:bg-tone-border sa:satin-pressed:[box-shadow:none]',
        ],
      },
      {
        variant: 'subtle',
        neutral: true,
        className: [
          'sa:bg-action-secondary-bg',
          'sa:satin-hover:bg-bg-pressed',
          'sa:satin-focus:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
          'sa:has-[button:focus-visible]:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
          'sa:satin-pressed:bg-bg-pressed sa:satin-pressed:[box-shadow:inset_0_0_0_var(--sa-border-width-strong)_var(--sa-border-strong)]',
        ],
      },
      {
        variant: 'subtle',
        neutral: false,
        className: [
          'sa:bg-tone-bg',
          'sa:satin-hover:bg-tone-border',
          'sa:satin-focus:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
          'sa:has-[button:focus-visible]:[box-shadow:0_0_0_2px_var(--sa-action-focus-ring)]',
          'sa:satin-pressed:bg-tone-border',
        ],
      },
    ],
    defaultVariants: { variant: 'subtle', size: 'md', neutral: true },
  },
)

type ChipBaseProps = Omit<VariantProps<typeof chipVariants>, 'neutral'> & {
  tone?: BadgeTone
  /** A status dot before the label. */
  dot?: boolean
  /** A 16px avatar before the label (an initials avatar or an image). */
  avatar?: React.ReactNode
  /** Shows the close button; called when it's clicked. */
  onRemove?: () => void
  /** Accessible name of the remove button. Defaults to the `removeItem` label with the chip's text ("Remove Design"). */
  removeLabel?: string
  disabled?: boolean
  children?: React.ReactNode
  className?: string
}

export type ChipProps = ChipBaseProps &
  Omit<React.ComponentProps<'button'>, keyof ChipBaseProps> & {
    'data-force'?: 'hover' | 'focus' | 'pressed'
  }

/** The Figma close glyph, 16 at 1.25 (14 at 1.09 on sm). */
function CloseGlyph({ size }: { size: 14 | 16 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none" aria-hidden>
      <path
        d="M4.50551 11.4951L8.0006 8M8.0006 8L11.4957 4.50491M8.0006 8L4.50551 4.50491M8.0006 8L11.4957 11.4951"
        stroke="currentColor"
        strokeWidth="1.25"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  )
}

export function Chip({
  className,
  variant = 'subtle',
  size = 'md',
  tone = 'neutral',
  dot = false,
  avatar,
  onRemove,
  removeLabel,
  disabled = false,
  children,
  type,
  ...props
}: ChipProps) {
  const labels = useSatinLabels()
  const neutral = tone === 'neutral'
  const iconSize = size === 'sm' ? 14 : 16
  const classes = cn(chipVariants({ variant, size, neutral }), className)
  const label = typeof children === 'string' ? children : undefined

  const content = (
    <>
      {dot && (
        // Dot slot: 4px in, a 16px box with an 8px status dot (status/green fg in Figma).
        <span data-slot="chip-dot" className="sa:-me-1 sa:flex sa:shrink-0 sa:items-center sa:ps-1" aria-hidden>
          <span className="sa:grid sa:size-4 sa:place-items-center">
            <span className="sa:size-2 sa:rounded-full sa:bg-status-green-fg" />
          </span>
        </span>
      )}
      {avatar && (
        <span
          data-slot="chip-avatar"
          className="sa:-me-1 sa:flex sa:shrink-0 sa:items-center sa:ps-1 sa:[&>*]:size-4 sa:[&>*]:rounded-full"
        >
          {avatar}
        </span>
      )}
      <span data-slot="chip-label" className={cn('sa:flex sa:shrink-0 sa:items-center sa:px-2', onRemove && 'sa:-me-1')}>
        {children}
      </span>
      {onRemove && (
        <span className="sa:flex sa:shrink-0 sa:items-center sa:pe-1">
          <button
            type="button"
            data-slot="chip-remove"
            disabled={disabled}
            aria-label={removeLabel ?? (label ? labels.removeItem(label) : labels.remove)}
            onClick={onRemove}
            className={cn(
              'sa:grid sa:shrink-0 sa:place-items-center sa:rounded-pill sa:focus-visible:outline-none',
              neutral ? 'sa:text-text-muted' : 'sa:text-tone-fg',
            )}
          >
            <CloseGlyph size={iconSize} />
          </button>
        </span>
      )}
    </>
  )

  if (onRemove) {
    // The chip is a span holding the remove button; id, aria-*, data-* and handlers go on it too.
    return (
      <span
        {...(props as React.ComponentProps<'span'>)}
        data-slot="chip"
        data-tone={tone}
        data-disabled={disabled || undefined}
        className={classes}
      >
        {content}
      </span>
    )
  }

  return (
    <button
      data-slot="chip"
      data-tone={tone}
      data-disabled={disabled || undefined}
      type={type ?? 'button'}
      disabled={disabled}
      className={classes}
      {...props}
    >
      {content}
    </button>
  )
}

/** The 16px initials avatar from Figma (Avatar 992:20199 at size 16): tone-bg, 7px semibold tone-fg. */
export function ChipAvatar({ initials, tone, className }: { initials: string; tone?: BadgeTone; className?: string }) {
  return (
    <span
      data-tone={tone}
      aria-hidden
      className={cn(
        'sa:grid sa:size-4 sa:shrink-0 sa:place-items-center sa:overflow-hidden sa:rounded-full sa:bg-tone-bg sa:text-[7px] sa:leading-2 sa:font-semibold sa:text-tone-fg',
        className,
      )}
    >
      {initials}
    </span>
  )
}

export { chipVariants }
